import type {
	IssueCommentCreatedEvent,
	IssuesOpenedEvent,
	PullRequestOpenedEvent,
	PullRequestReviewCommentCreatedEvent,
} from "@octokit/webhooks-types";

import type {
	GitHubComment,
	GitHubReaction,
	GitHubUser,
	OctokitClient,
	RepoRef,
	TriggerInfo,
	TriggerSource,
} from "./types.ts";

type SupportedWebhookPayload =
	| IssueCommentCreatedEvent
	| IssuesOpenedEvent
---
{
  "name": "@octokit/openapi-webhooks-types",
  "description": "Generated TypeScript definitions based on GitHub's OpenAPI spec for api.github.com",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/octokit/openapi-webhooks.git",
    "directory": "packages/openapi-webhooks-types"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "version": "12.2.0",
  "main": "",
  "types": "types.d.ts",
  "author": "wolfy1339 <webmaster@wolfy1339.com>",
  "license": "MIT"
}
